async function door_verifyOwnNode(raw) {
    const ticket = door_nodeChecks.take();
    const settle = (next) => {
        if (!door_nodeChecks.isCurrent(ticket))
            return;
        door_state.own = next;
        door_render();
    };
    if (raw === null || raw.trim().length === 0) {
        settle({ state: 'none' });
        return;
    }
    const shape = door_checkDoorNodeUrl(raw);
    if (!shape.ok) {
        settle({ state: 'refused', why: shape.reason, detail: null });
        return;
    }
    settle({ state: 'checking', url: shape.url, host: shape.host });
    try {
        const said = await door_ownReader(shape.url).getChainId();
        if (said !== door_CHAIN_ID) {
            settle({ state: 'refused', why: 'wrong-chain', detail: String(said) });
            return;
        }
        const at = await door_ownReader(shape.url).getBlockNumber().catch(() => null);
        settle({ state: 'live', url: shape.url, host: shape.host, at });
    }
    catch (e) {
        settle({
            state: 'refused',
            why: 'silent',
            detail: e instanceof Error ? e.message.split('\n')[0].slice(0, 160) : null,
        });
    }
}
