        const probe = door_readSimulationFailure(e);
        door_state.notice = {
            kind: 'refused',
            text: probe.kind === 'refused'
                ? (door_revertSentence(probe.name, door_lang) ?? door_t(door_T.refusedNoName))
                : `${door_t(door_T.walletRefused)} ${probe.detail}`.trim(),
        };
