async function door_connect() {
    const provider = door_injected();
    if (!provider)
        return;
    const accounts = (await provider.request({ method: 'eth_requestAccounts' }));
    const chainIdHex = (await provider.request({ method: 'eth_chainId' }));
    door_state.account = (accounts[0] ?? null);
    door_state.walletChainId = Number.parseInt(chainIdHex, 16);
    provider.on?.('accountsChanged', (...args) => {
        const next = args[0]?.[0] ?? null;
        door_state.account = next;
        door_state.verdicts = {};
        void door_readDeals();
        void door_askRecordPress();
    });
    provider.on?.('chainChanged', (...args) => {
        door_state.walletChainId = Number.parseInt(String(args[0]), 16);
        door_render();
    });
    door_render();
    await door_readDeals();
    await door_askRecordPress();
}
